"use client";

import { AnimatePresence } from "motion/react";
import { useEffect, useId, useRef, useState } from "react";

import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";

import { BlockFrame } from "../parts/block-frame";
import { PlusIcon } from "../parts/icons";
import { roundCents } from "./money";
import { FIRST_LINES, FIRST_NOTE, type InvoiceLine, lineAmount, type TaxRate } from "./invoice-studio/data";
import { InvoiceTotals } from "./invoice-studio/invoice-totals";
import { LineRow } from "./invoice-studio/line-row";
import { SaveBar, type SaveState } from "./invoice-studio/save-bar";

interface Draft {
  lines: InvoiceLine[];
  taxRate: TaxRate;
  note: string;
}

const FIRST_DRAFT: Draft = { lines: FIRST_LINES, taxRate: "8.5", note: FIRST_NOTE };
const TIME = new Intl.DateTimeFormat("en-US", { hour: "numeric", minute: "2-digit" });

/**
 * An invoice a clinic owner edits in place: change a line, add or remove one,
 * pick the tax rate, and the totals roll to match. Saving is an explicit step,
 * and the draft says when it has changes that are not saved yet.
 */
export function InvoiceStudio({ className }: { className?: string }) {
  const titleId = useId();
  const noteId = useId();
  const [draft, setDraft] = useState<Draft>(FIRST_DRAFT);
  const [saved, setSaved] = useState<Draft>(FIRST_DRAFT);
  const [saving, setSaving] = useState(false);
  const [savedAt, setSavedAt] = useState<string | null>(null);
  const nextId = useRef(1);
  const [focusId, setFocusId] = useState<string | null>(null);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => () => {
    if (timer.current) clearTimeout(timer.current);
  }, []);

  // A new line takes the focus once it is on screen, so the person can type its description straight away.
  useEffect(() => {
    if (!focusId) return;
    document.getElementById(`${titleId}-${focusId}`)?.focus();
    setFocusId(null);
  }, [focusId, titleId]);

  const dirty = JSON.stringify(draft) !== JSON.stringify(saved);
  const state: SaveState = saving ? { kind: "saving" } : dirty ? { kind: "dirty" } : { kind: "saved", at: savedAt };

  const subtotal = roundCents(draft.lines.reduce((total, line) => total + lineAmount(line), 0));
  const tax = roundCents((subtotal * Number(draft.taxRate)) / 100);

  const updateLine = (next: InvoiceLine) =>
    setDraft((current) => ({ ...current, lines: current.lines.map((line) => (line.id === next.id ? next : line)) }));
  const removeLine = (id: string) => setDraft((current) => ({ ...current, lines: current.lines.filter((line) => line.id !== id) }));
  const addLine = () => {
    const id = `new-${nextId.current++}`;
    setFocusId(id);
    setDraft((current) => ({ ...current, lines: [...current.lines, { id, description: "", quantity: "1", rate: "0" }] }));
  };

  const save = () => {
    setSaving(true);
    const snapshot = draft;
    timer.current = setTimeout(() => {
      setSaved(snapshot);
      setSavedAt(TIME.format(new Date()));
      setSaving(false);
    }, 900);
  };

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-wrap items-start justify-between gap-4 border-b border-border px-5 py-4">
        <div>
          <p className="text-sm font-semibold">Fernhill</p>
          <p className="text-sm text-muted-foreground">Invoice FH-2026-118</p>
        </div>
        <dl className="grid grid-cols-[auto_auto] gap-x-3 text-sm @md:text-right">
          <dt className="text-muted-foreground">Issued</dt>
          <dd>Nov 3, 2026</dd>
          <dt className="text-muted-foreground">Due</dt>
          <dd>Dec 3, 2026</dd>
        </dl>
      </header>

      <div className="flex flex-col gap-6 px-5 py-6">
        <div className="flex flex-wrap items-end justify-between gap-6">
          <h2 id={titleId} className="text-4xl font-semibold tracking-tight">
            Invoice
          </h2>
          <div className="grid grid-cols-2 gap-6 text-sm">
            <address className="not-italic">
              <span className="block text-muted-foreground">From</span>
              <span className="block font-medium">Fernhill Scheduling</span>
              <span className="block text-muted-foreground">18 Tanner Row, Leeds</span>
            </address>
            <address className="not-italic">
              <span className="block text-muted-foreground">Bill to</span>
              <span className="block font-medium">Harbour Street Physio</span>
              <span className="block text-muted-foreground">4 Quayside, Whitby</span>
            </address>
          </div>
        </div>

        <div>
          <div
            aria-hidden="true"
            className="hidden grid-cols-[1fr_4.5rem_6.5rem_6.5rem_2.25rem] gap-x-2 border-b border-border pb-2 text-xs text-muted-foreground @xl:grid"
          >
            <span>Work</span>
            <span className="text-right">Qty</span>
            <span className="text-right">Rate</span>
            <span className="text-right">Amount</span>
            <span />
          </div>
          <ul aria-label="Invoice lines">
            <AnimatePresence initial={false}>
              {draft.lines.map((line, index) => (
                <LineRow
                  key={line.id}
                  line={line}
                  number={index + 1}
                  onChange={updateLine}
                  onRemove={() => removeLine(line.id)}
                  canRemove={draft.lines.length > 1}
                  descriptionId={`${titleId}-${line.id}`}
                />
              ))}
            </AnimatePresence>
          </ul>
          <Button type="button" variant="ghost" size="sm" onClick={addLine} className="mt-2">
            <PlusIcon aria-hidden="true" className="size-4" />
            Add line item
          </Button>
        </div>

        <div className="flex flex-col gap-6 @xl:flex-row @xl:items-start @xl:justify-between">
          <div className="flex w-full flex-col gap-1.5 @xl:max-w-72">
            <label htmlFor={noteId} className="text-sm text-muted-foreground">
              Note to the clinic
            </label>
            <Textarea
              id={noteId}
              value={draft.note}
              onChange={(event) => setDraft((current) => ({ ...current, note: event.target.value }))}
            />
          </div>
          <InvoiceTotals
            subtotal={subtotal}
            tax={tax}
            taxRate={draft.taxRate}
            onTaxRateChange={(taxRate) => setDraft((current) => ({ ...current, taxRate }))}
          />
        </div>
      </div>

      <SaveBar state={state} onSave={save} onDiscard={() => setDraft(saved)} />
    </BlockFrame>
  );
}

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

