const CENTS = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", minimumFractionDigits: 2, maximumFractionDigits: 2 });
const WHOLE = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 });

/** A dollar amount with cents, such as $1,240.50. */
export const formatCents = (value: number) => CENTS.format(value);

/** A dollar amount rounded to whole dollars, such as $48. */
export const formatDollars = (value: number) => WHOLE.format(Math.round(value));

/** A signed dollar amount with cents, such as +$120.00 or −$48.20, for a ledger row. */
export const formatSigned = (value: number) => `${value < 0 ? "−" : "+"}${CENTS.format(Math.abs(value))}`;

/** Rounds to whole cents, so totals add up the way an invoice prints them. */
export const roundCents = (value: number) => Math.round(value * 100) / 100;

/** One line of the invoice. Quantity and rate stay as typed text, so a half-typed figure is never rewritten under the cursor. */
export interface InvoiceLine {
  id: string;
  description: string;
  quantity: string;
  rate: string;
}

/** The tax rates the invoice offers, in percent. */
export const TAX_RATES = ["0", "5", "8.5"] as const;

/** One of the offered tax rates. */
export type TaxRate = (typeof TAX_RATES)[number];

/** The saved draft the block opens with. */
export const FIRST_LINES: InvoiceLine[] = [
  { id: "plan", description: "Fernhill clinic plan, 4 practitioners, November", quantity: "4", rate: "39" },
  { id: "page", description: "Booking page set-up and room import", quantity: "1", rate: "250" },
  { id: "texts", description: "Appointment reminder texts", quantity: "1200", rate: "0.04" },
];

/** The note printed under the lines. */
export const FIRST_NOTE = "Thank you for booking with Fernhill. Payment is due within 30 days by bank transfer.";

/** A typed figure as a number. Anything that is not a number counts as nothing. */
export const readFigure = (text: string) => {
  const value = Number.parseFloat(text);
  return Number.isFinite(value) && value > 0 ? value : 0;
};

/** The amount of one line: quantity times rate. */
export const lineAmount = (line: InvoiceLine) => readFigure(line.quantity) * readFigure(line.rate);

"use client";

import { SegmentedControl } from "@/components/motion/segmented-control";

import { RollingText } from "../../parts/rolling-text";
import { formatCents } from "../money";
import { TAX_RATES, type TaxRate } from "./data";

/** Props for the invoice's totals. */
export interface InvoiceTotalsProps {
  subtotal: number;
  tax: number;
  taxRate: TaxRate;
  onTaxRateChange: (rate: TaxRate) => void;
}

const RATE_OPTIONS = TAX_RATES.map((rate) => ({ value: rate, label: `${rate}%` }));

/**
 * The subtotal, the tax with its rate and the total due. Each figure rolls to
 * its new value, and the total is announced once it settles.
 */
export function InvoiceTotals({ subtotal, tax, taxRate, onTaxRateChange }: InvoiceTotalsProps) {
  const total = subtotal + tax;
  return (
    <dl className="flex w-full flex-col gap-2.5 text-sm @xl:max-w-72">
      <div className="flex items-center justify-between gap-4">
        <dt className="text-muted-foreground">Subtotal</dt>
        <dd>
          <RollingText text={formatCents(subtotal)} />
        </dd>
      </div>
      <div className="flex items-center justify-between gap-4">
        <dt className="flex items-center gap-2 text-muted-foreground">
          Tax
          <SegmentedControl aria-label="Tax rate" options={RATE_OPTIONS} value={taxRate} onValueChange={onTaxRateChange} />
        </dt>
        <dd>
          <RollingText text={formatCents(tax)} />
        </dd>
      </div>
      <div className="mt-1 flex items-baseline justify-between gap-4 border-t border-border pt-3">
        <dt className="font-medium">Total due</dt>
        <dd aria-live="polite" aria-atomic="true">
          <RollingText text={formatCents(total)} className="text-2xl font-semibold tracking-tight" />
        </dd>
      </div>
    </dl>
  );
}

import { NumberTicker } from "@/components/motion/number-ticker";
import { cn } from "@/lib/utils";

/** Props for a formatted figure whose digits roll. */
export interface RollingTextProps {
  /** A figure that is already formatted, such as "$3,577" or "8.2 min". */
  text: string;
  className?: string;
}

/**
 * Shows a formatted figure and rolls each digit to its new value when the
 * text changes, as a counter does. Signs, separators and units stay still.
 * Each glyph is keyed by its place from the right, so a digit keeps its
 * column when the figure grows. It is for text that already has another
 * spoken source: the rolling columns are hidden from screen readers.
 */
export function RollingText({ text, className }: RollingTextProps) {
  const glyphs = [...text];
  return (
    <span className={cn("inline-flex tabular-nums", className)}>
      <span className="sr-only">{text}</span>
      <span aria-hidden="true" className="inline-flex">
        {glyphs.map((glyph, index) => {
          const place = glyphs.length - 1 - index;
          return glyph >= "0" && glyph <= "9" ? (
            <NumberTicker key={place} value={Number(glyph)} />
          ) : (
            <span key={place} className="whitespace-pre">
              {glyph}
            </span>
          );
        })}
      </span>
    </span>
  );
}

"use client";

import { motion, useReducedMotion } from "motion/react";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";

import { TrashIcon } from "../../parts/icons";
import { RollingText } from "../../parts/rolling-text";
import { formatCents } from "../money";
import { type InvoiceLine, lineAmount } from "./data";

/** Props for one editable invoice line. */
export interface LineRowProps {
  line: InvoiceLine;
  /** The line's place, counted from one, so each field has a name a screen reader can tell apart. */
  number: number;
  onChange: (line: InvoiceLine) => void;
  onRemove: () => void;
  /** The last line keeps its row: an invoice needs at least one. */
  canRemove: boolean;
  /** The description field's id, so a new line can take the focus. */
  descriptionId: string;
}

/**
 * One invoice line: description, quantity, rate, the amount they make and a
 * remove button. A new or removed line opens or closes its height; with
 * reduced motion it only fades.
 */
export function LineRow({ line, number, onChange, onRemove, canRemove, descriptionId }: LineRowProps) {
  const reduceMotion = useReducedMotion();
  const name = line.description.trim() || `line ${number}`;
  const hidden = reduceMotion ? { opacity: 0 } : { opacity: 0, height: 0 };
  const shown = reduceMotion ? { opacity: 1 } : { opacity: 1, height: "auto" };

  return (
    <motion.li
      layout={reduceMotion ? false : "position"}
      initial={hidden}
      animate={shown}
      exit={hidden}
      transition={{ duration: reduceMotion ? 0.12 : 0.22, ease: [0.165, 0.84, 0.44, 1] }}
      className="overflow-hidden"
    >
      <div className="grid grid-cols-[4.5rem_1fr_auto_2.25rem] items-center gap-x-2 gap-y-2 border-b border-border py-2.5 @xl:grid-cols-[1fr_4.5rem_6.5rem_6.5rem_2.25rem]">
        <Input
          id={descriptionId}
          aria-label={`Description, line ${number}`}
          value={line.description}
          placeholder="What the work was"
          onChange={(event) => onChange({ ...line, description: event.target.value })}
          className="col-span-4 h-8 @xl:col-span-1"
        />
        <Input
          aria-label={`Quantity, ${name}`}
          inputMode="decimal"
          value={line.quantity}
          onChange={(event) => onChange({ ...line, quantity: event.target.value })}
          className="h-8 text-right"
        />
        <div className="flex items-center gap-1">
          <span aria-hidden="true" className="text-sm text-muted-foreground">
            $
          </span>
          <Input
            aria-label={`Rate in dollars, ${name}`}
            inputMode="decimal"
            value={line.rate}
            onChange={(event) => onChange({ ...line, rate: event.target.value })}
            className="h-8 text-right"
          />
        </div>
        <RollingText text={formatCents(lineAmount(line))} className="justify-end text-sm font-medium" />
        <Button
          type="button"
          variant="ghost"
          size="icon"
          aria-label={`Remove ${name}`}
          disabled={!canRemove}
          onClick={onRemove}
          className="size-8"
        >
          <TrashIcon aria-hidden="true" className="size-4" />
        </Button>
      </div>
    </motion.li>
  );
}

"use client";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { CheckIcon } from "../../parts/icons";
import { STATUS_TEXT } from "../../lib/status";
import { LoaderIcon } from "../../auth/icons";

/** Where the draft stands against its last save. */
export type SaveState = { kind: "saved"; at: string | null } | { kind: "dirty" } | { kind: "saving" };

/** Props for the save row. */
export interface SaveBarProps {
  state: SaveState;
  onSave: () => void;
  onDiscard: () => void;
}

/**
 * The explicit save step: a line that says whether the draft has unsaved
 * changes, a button to throw them away and one to save them. The line is a
 * live region, so a screen reader hears when the save lands.
 */
export function SaveBar({ state, onSave, onDiscard }: SaveBarProps) {
  const message =
    state.kind === "dirty"
      ? "Unsaved changes"
      : state.kind === "saving"
        ? "Saving the draft"
        : state.at
          ? `Draft saved at ${state.at}`
          : "All changes saved";
  return (
    <div className="flex flex-wrap items-center justify-between gap-3 border-t border-border px-5 py-4">
      <p role="status" className="flex items-center gap-2 text-sm text-muted-foreground">
        {state.kind === "dirty" ? (
          <span aria-hidden="true" className="size-2 rounded-full bg-chart-3" />
        ) : state.kind === "saved" ? (
          <CheckIcon aria-hidden="true" className={cn("size-4", STATUS_TEXT.good)} />
        ) : null}
        {message}
      </p>
      <div className="flex gap-2">
        <Button type="button" variant="ghost" size="sm" disabled={state.kind !== "dirty"} onClick={onDiscard}>
          Discard changes
        </Button>
        <Button type="button" size="sm" disabled={state.kind !== "dirty"} aria-busy={state.kind === "saving"} onClick={onSave}>
          <span aria-hidden="true" className="flex size-4 items-center justify-center">
            {state.kind === "saving" ? <LoaderIcon className="size-4 motion-safe:animate-spin" /> : null}
          </span>
          Save draft
        </Button>
      </div>
    </div>
  );
}

/** The three states a figure or a row can be in. */
export type Status = "good" | "watch" | "bad";

/** The text colour for each state. Each one passes 4.5 to 1 on a card in both themes. */
export const STATUS_TEXT = {
  good: "text-marketing-green-ink",
  watch: "text-marketing-amber-ink",
  bad: "text-marketing-orange-ink",
} satisfies Record<Status, string>;

/** A tinted surface for each state, for a pill or a cell. Pair it with the matching text colour. */
export const STATUS_SURFACE = {
  good: "bg-marketing-green-surface",
  watch: "bg-marketing-amber-surface",
  bad: "bg-marketing-orange-surface",
} satisfies Record<Status, string>;

/** The word a screen reader and a label use for each state. Colour never carries a state alone. */
export const STATUS_WORD = {
  good: "Good",
  watch: "Watch",
  bad: "At risk",
} satisfies Record<Status, string>;

"use client";

